import re


_DURATION_RE = re.compile(
    r"(?i)^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$"
)


def parse_duration(s):
    """Parse a duration string like '1h30m' into seconds."""
    if not isinstance(s, str):
        return 0

    s = s.strip()
    if not s:
        return 0

    match = _DURATION_RE.fullmatch(s)
    if not match:
        return 0

    hours, minutes, seconds = match.groups()
    if hours is None and minutes is None and seconds is None:
        return 0

    return (
        (int(hours) if hours is not None else 0) * 3600
        + (int(minutes) if minutes is not None else 0) * 60
        + (int(seconds) if seconds is not None else 0)
    )
