import re


def parse_duration(s):
    """Parse a duration string like '1h30m' into seconds."""
    if not isinstance(s, str):
        return 0

    text = s.strip()
    if not text:
        return 0

    # Ensure the whole string is composed of "<int><unit>" tokens (with optional spaces).
    if not re.fullmatch(r"(?:\d+\s*[hmsHMS]\s*)+", text):
        return 0

    total_seconds = 0
    seen_units = set()
    unit_to_seconds = {"h": 3600, "m": 60, "s": 1}

    for value_text, unit_text in re.findall(r"(\d+)\s*([hmsHMS])", text):
        unit = unit_text.lower()
        if unit in seen_units:
            return 0  # Reject repeated units like "1h30m10h"
        seen_units.add(unit)
        total_seconds += int(value_text) * unit_to_seconds[unit]

    return total_seconds
```

